export function reflectionProbeBlendWeights(probes,point,normal=[0,0,0],ray=[0,0,0]){let remaining=1;const values=probes.map(p=>{const raw=probeInfluenceWeight(p,point,normal,ray),weight=raw*remaining;if(p.p.priorityBlend)remaining*=1-raw;return weight;}),total=values.reduce((a,b)=>a+b,0);return {weights:values.map(v=>v/Math.max(1,total)),base:1-Math.min(1,total)};}
export function probeMapLayout(map){const image=map?.image,width=image?.width||1,height=image?.height||64;return [1/width,1/height,Math.log2(height)-2];}
export function probeBlendUniforms(){const result={hbProbeLightmapMixing:{value:false},hbProbeBaseMap:{value:null},hbProbeBaseRotation:{value:new Matrix3()},hbProbeBaseLayout:{value:new Vector3()},hbProbeBaseOptions:{value:new Vector3()}};for(let i=0;i<2;i++){for(const key of ['Center','Min','Max','FaceScale','Layout'])result['hbProbe'+key+i]={value:new Vector3()};for(const key of ['LocalX','LocalY','LocalZ','Options','ProjectionMinimum','ProjectionMaximum','ProjectionX','ProjectionY','ProjectionZ'])result['hbProbe'+key+i]={value:new Vector4()};for(const key of probeInfluenceFields)result['hbProbe'+key[0].toUpperCase()+key.slice(1)+i]={value:new Vector4()};result['hbProbeIntensity'+i]={value:0};result['hbProbeMap'+i]={value:null};}return result;}
export function updateProbeBlendUniforms(u,probes,maps,base,intensity,rotation){if(rotation)u.hbProbeBaseRotation.value.copy(rotation);u.hbProbeBaseMap.value=base||maps[0]||maps[1]||null;u.hbProbeBaseLayout.value.fromArray(probeMapLayout(u.hbProbeBaseMap.value));u.hbProbeBaseOptions.value.set(base?1:0,intensity,0);for(let i=0;i<2;i++){const p=probes[i],map=maps[i]||maps[0]||maps[1]||base||null;u['hbProbeMap'+i].value=map;u['hbProbeLayout'+i].value.fromArray(probeMapLayout(map));u['hbProbeOptions'+i].value.set(p?.p.diffuseIntensity??1,p?.p.boxProjection?1:0,p?.p.blendDistance||0,p?(p.p.volumeShape==='sphere'?3:1)+(p.p.priorityBlend?4:0):0);u['hbProbeIntensity'+i].value=p?.p.intensity||0;const influence=probeInfluenceSettings(p?.p||{});for(const key of probeInfluenceFields)u['hbProbe'+key[0].toUpperCase()+key.slice(1)+i].value.fromArray(influence[key]);const projection=probeProjectionSettings(p?.projection);for(const key of probeProjectionFields)u['hbProbe'+key[0].toUpperCase()+key.slice(1)+i].value.fromArray(projection[key]);if(p){const b=p.localBox;u['hbProbeCenter'+i].value.fromArray(p.center);u['hbProbeMin'+i].value.fromArray(b.minimum);u['hbProbeMax'+i].value.fromArray(b.maximum);for(const key of ['LocalX','LocalY','LocalZ','FaceScale'])u['hbProbe'+key+i].value.fromArray(b[key[0].toLowerCase()+key.slice(1)]);}}}

// Three's licensed CubeUV addressing, with layout passed per texture instead of
// global defines. Different probe resolutions share the same compiled program.
const cubeChunk=ShaderChunk.cube_uv_reflection_fragment,sampleStart=cubeChunk.indexOf('vec3 bilinearCubeUV'),sampleEnd=cubeChunk.indexOf('#define cubeUV_r0');
if(sampleStart<0||sampleEnd<=sampleStart)throw Error('설치된 Three의 CubeUV 샘플러 계약을 확인하세요.');
const sampler=cubeChunk.slice(sampleStart,sampleEnd)
 .replace('bilinearCubeUV( sampler2D envMap, vec3 direction, float mipInt )','hbProbeBilinear( sampler2D envMap, vec3 direction, float mipInt, vec3 cubeLayout )').replaceAll('CUBEUV_MAX_MIP','cubeLayout.z').replaceAll('CUBEUV_TEXEL_WIDTH','cubeLayout.x').replaceAll('CUBEUV_TEXEL_HEIGHT','cubeLayout.y');
export const probeBlendGLSL=probeVolumeGLSL+probeProjectionGLSL+probeInfluenceGLSL+'\nvarying vec3 hbProbePosition;\n'+`
#ifdef ENVMAP_TYPE_CUBE_UV
uniform sampler2D hbProbeBaseMap;uniform mat3 hbProbeBaseRotation;uniform vec3 hbProbeBaseLayout,hbProbeBaseOptions;
${[0,1].map(i=>`uniform sampler2D hbProbeMap${i};uniform vec3 hbProbeCenter${i},hbProbeMin${i},hbProbeMax${i},hbProbeFaceScale${i},hbProbeLayout${i};uniform vec4 hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i},hbProbeOptions${i},hbProbeProjectionMinimum${i},hbProbeProjectionMaximum${i},hbProbeProjectionX${i},hbProbeProjectionY${i},hbProbeProjectionZ${i},hbProbeBlendPositive${i},hbProbeBlendNegative${i},hbProbeFadePositive${i},hbProbeFadeNegative${i},hbProbeNormalPositive${i},hbProbeNormalNegative${i};uniform float hbProbeIntensity${i};`).join('\n')}
${sampler}
vec3 hbProbeSample(sampler2D map,vec3 direction,float roughness,vec3 cubeLayout){float mip=clamp(roughnessToMip(roughness),cubeUV_m0,cubeLayout.z),whole=floor(mip),fraction=fract(mip);vec3 first=hbProbeBilinear(map,direction,whole,cubeLayout);return fraction==0.0?first:mix(first,hbProbeBilinear(map,direction,whole+1.0,cubeLayout),fraction);}
${[0,1].map(i=>`float hbProbeFade${i}(vec3 normal,vec3 ray){vec3 local=hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i});return min(hbProbeOptions${i}.w,1.0)*hbProbeInfluenceFade(local,hbProbeMin${i},hbProbeMax${i},hbProbeFaceScale${i},hbProbeOptions${i}.z,mod(hbProbeOptions${i}.w,4.0)>1.5,hbProbePosition,hbProbeCenter${i},normal,ray,hbProbeBlendPositive${i},hbProbeBlendNegative${i},hbProbeFadePositive${i},hbProbeFadeNegative${i},hbProbeNormalPositive${i},hbProbeNormalNegative${i},hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i});}
vec3 hbProbeRay${i}(vec3 ray){return hbProbeOptions${i}.y<.5?ray:hbProbeProjectionMinimum${i}.w>.5?hbProxyDirection(hbProbePosition,ray,hbProbeCenter${i},hbProbeProjectionMinimum${i},hbProbeProjectionMaximum${i},hbProbeProjectionX${i},hbProbeProjectionY${i},hbProbeProjectionZ${i}):mod(hbProbeOptions${i}.w,4.0)>1.5?hbProbeSphereProject(hbProbePosition,ray,hbProbeCenter${i},hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeLocalRay(ray,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeMax${i}.x):hbProbeProject(hbProbePosition,ray,hbProbeCenter${i},hbProbeLocalPoint(hbProbePosition,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeLocalRay(ray,hbProbeLocalX${i},hbProbeLocalY${i},hbProbeLocalZ${i}),hbProbeMin${i},hbProbeMax${i});}`).join('\n')}
${probeLightmapMixGLSL}
vec3 hbProbeMixedSample(sampler2D map,vec3 direction,float roughness,vec3 cubeLayout,float intensity,vec3 normal,bool diffuse){vec3 value=hbProbeSample(map,direction,roughness,cubeLayout)*intensity;
#ifdef USE_LIGHTMAP
if(!diffuse&&hbProbeLightmapMixing&&lightMapIntensity>0.0&&roughness>.1&&dot(normal,normal)>0.0)value*=hbProbeLightmapScale(PI*hbProbeSample(map,normal,1.0,cubeLayout)*intensity,roughness);
#endif
return value;}
vec3 hbProbeLight(vec3 ray,float roughness,bool diffuse,vec3 normal){float a=hbProbeFade0(normal,ray),b=hbProbeFade1(normal,ray);if(hbProbeOptions0.w>=4.0)b*=1.0-a;float total=a+b;vec3 light=vec3(0);if(a>0.0)light+=hbProbeMixedSample(hbProbeMap0,diffuse?ray:hbProbeRay0(ray),roughness,hbProbeLayout0,hbProbeIntensity0,normal,diffuse)*(diffuse?hbProbeOptions0.x:1.0)*a;if(b>0.0)light+=hbProbeMixedSample(hbProbeMap1,diffuse?ray:hbProbeRay1(ray),roughness,hbProbeLayout1,hbProbeIntensity1,normal,diffuse)*(diffuse?hbProbeOptions1.x:1.0)*b;light/=max(1.0,total);if(hbProbeBaseOptions.x>0.5&&total<1.0)light+=hbProbeSample(hbProbeBaseMap,hbProbeBaseRotation*ray,roughness,hbProbeBaseLayout)*hbProbeBaseOptions.y*(1.0-total);return light;}
vec3 hbProbeLight(vec3 ray,float roughness,bool diffuse){return hbProbeLight(ray,roughness,diffuse,vec3(0));}
#endif
`;
export function probeBlendPhysicalGLSL(){return probeBlendGLSL+'\n'+ShaderChunk.envmap_physical_pars_fragment.replace(/vec4 envMapColor = textureCubeUV\([^;]+;/g,'').replace('return PI * envMapColor.rgb * envMapIntensity;','return PI * hbProbeLight(worldNormal,1.0,true,worldNormal);').replace('return envMapColor.rgb * envMapIntensity;','return hbProbeLight(reflectVec,roughness,false,inverseTransformDirection(normal,viewMatrix));');}
